def transform(grid):
    from collections import Counter

    # Background
    bg_counts = Counter()
    for row in grid:
        for cell in row:
            bg_counts[cell] += 1
    bg = bg_counts.most_common(1)[0][0]

    H, W = len(grid), len(grid[0])
    output = [[bg] * W for _ in range(H)]

    signal_rows = {}

    for c in range(W):
        # Find activation row: first r where from r onward, at least 5 non-bg values
        for r in range(H):
            remainder = [grid[kr][c] for kr in range(r, H) if grid[kr][c] != bg]
            if len(remainder) >= 5:
                signal_rows[c] = r
                break

    if not signal_rows:
        return output

    min_activation = min(signal_rows.values())

    for r in range(min_activation):
        for c in range(W):
            output[r][c] = bg

    for c, row in signal_rows.items():
        colors = [grid[kr][c] for kr in range(H) if grid[kr][c] != bg]
        if colors:
            signal_color = Counter(colors).most_common(1)[0][0]
            for kr in range(row, H):
                output[kr][c] = signal_color

    return output
